.msg-me.is-single {
  margin-bottom: -6px !important;
}

/* ============================================================
   11. 拍一拍
   ============================================================ */

@keyframes nuo-bubble-live-left {
  0% {
    opacity: 0;
    transform: translate(-50%, 0) scale(0.2) rotate(0deg);
  }
  15% {
    opacity: 1;
    transform: translate(calc(-50% - 12px), -18px) scale(1.3) rotate(-14deg);
  }
  40% {
    opacity: 0.9;
    transform: translate(calc(-50% + 10px), -44px) scale(1.1) rotate(12deg);
  }
  70% {
    opacity: 0.7;
    transform: translate(calc(-50% - 18px), -72px) scale(0.9) rotate(-18deg);
  }
  100% {
    opacity: 0;
    transform: translate(calc(-50% + 4px), -102px) scale(0.3) rotate(20deg);
  }
}

@keyframes nuo-bubble-live-right {
  0% {
    opacity: 0;
    transform: translate(-50%, 0) scale(0.2) rotate(0deg);
  }
  15% {
    opacity: 1;
    transform: translate(calc(-50% + 14px), -16px) scale(1.2) rotate(15deg);
  }
  45% {
    opacity: 0.9;
    transform: translate(calc(-50% - 14px), -46px) scale(1.0) rotate(-12deg);
  }
  75% {
    opacity: 0.65;
    transform: translate(calc(-50% + 20px), -78px) scale(0.8) rotate(22deg);
  }
  100% {
    opacity: 0;
    transform: translate(calc(-50% - 8px), -108px) scale(0.3) rotate(-14deg);
  }
}

[class*="pat-bounce"],
