/*⁣‍‌‌⁠‍‍⁠​​‌⁠​‌​​⁠⁠⁠‍‍⁠​​⁠⁠⁠​‍‌‌⁠⁠‍‌‌​‍⁠⁠​⁠‌⁠​‍⁠‌⁠‌‌​‍​‌‌‍‌⁠​‌‍‍‌​⁣ 今日转晴-深灰 by Want 禁止二传 可二改自用 */
/* =======================================================
   ======================================================= */
   定制主题：方圆高透果冻泡泡 (绝杀头像与背景板)
======================================= */
/* 1. 全局背景留空 */
div.chat-detail-screen .chat-messages-area { background: transparent !important; }

/* =======================================
   2. 顶栏与底栏（全宽毛玻璃 + 超大粉色包裹药丸）
======================================= */
:root {
  /* 转账卡片定制 */
  --transfer-card-width: 190px !important; /* 加宽防止换行 */ /* 缩小宽度 */
  --transfer-me-card-bg: rgba(180, 230, 255, 0.75) !important; /* 深一点的蓝色毛玻璃 */
  --transfer-them-card-bg: rgba(200, 200, 200, 0.4) !important; /* 深一点的灰色毛玻璃 */
  --transfer-me-card-border: none !important;
  --transfer-them-card-border: none !important;
  --transfer-me-card-shadow: none !important;
  --transfer-them-card-shadow: none !important;

  /* 纯色文字气泡：左浅灰，右深灰。 */
  --bubble-me-bg: #5b5d61 !important;
  --bubble-them-bg: #f1f2f3 !important;
  --bubble-me-bg-gradient: none !important;
  --bubble-them-bg-gradient: none !important;
  --bubble-me-color: #ffffff !important;
  --bubble-them-color: #000000 !important;
  --bubble-me-backdrop: none !important;
  --bubble-them-backdrop: none !important;
  --bubble-me-shadow: none !important;
  --bubble-them-shadow: none !important;
  --bubble-me-border: none !important;
  --bubble-them-border: none !important;
  --bubble-me-radius: 20px !important;
  --bubble-them-radius: 20px !important;
  --bubble-me-padding: 6px 12px !important;
  --bubble-them-padding: 6px 12px !important;
  --bubble-me-line-height: 1.4 !important;
  --bubble-them-line-height: 1.4 !important;
  --chat-header-bg: #f1f2f3 !important;
  --chat-header-blur: 0px !important;
  --chat-header-border: transparent !important;
  --info-btn-icon: url('https://i.img402.dev/p6o6escwyp.png') !important;
  --input-box-padding: 0px 10px 0px 4px !important; /* 强制光标极度靠左 */

  /* 彻底杀死底栏自带的输入框胶囊样式 */
  --input-box-bg: transparent !important;
  --input-box-border: none !important;
  --input-box-shadow: none !important;
}

/* 顶栏保持毛玻璃 */
/* 顶栏定制：居中标题、点击返回、电话视频隐身、右上角天使、变窄 */
div.chat-detail-screen .header-avatar-container { display: none !important; }

/* 强行隐身电话、视频按钮 */
div.chat-detail-screen .header-btn-video {
  opacity: 0 !important;
  transform: translateY(8px) !important;
}

/* 标题组恢复居中对齐 */

div.chat-detail-screen .chat-header-subtitle { display: none !important; }

/* 返回按钮隐身，并把它瞬间移动到屏幕正中间，覆盖在标题文字上！ */
div.chat-detail-screen .header-btn-back {
  opacity: 0 !important;
  position: absolute !important;
  left: -2px !important; /* 跟着向左平移12px */
  top: 50% !important;
  transform: translateY(calc(-50% + 24px)) !important; /* 继续下沉6px，共24px */
  width: 160px !important; /* 覆盖左边大片区域，保证点击文字会点到它 */
  height: 50px !important;
  z-index: 30 !important;
}

/* 右上角 i 按钮替换为天使 (终极无情屠杀原生图标) */
/* 绝杀按钮内部的一切原生元素（不管是 svg, img 还是伪元素），保证绝对不会出现叠图！ */
div.chat-detail-screen .header-btn-info *,
div.chat-detail-screen .header-btn-info::before,
div.chat-detail-screen .header-btn-info::after {
  display: none !important;
  opacity: 0 !important;
  background-image: none !important;
}

div.chat-detail-screen .header-btn-info {
  transform: translateY(0px) !important;
  background-image: var(--info-btn-icon) !important;
  background-size: contain !important; /* 保证图片显示完整不被裁切 */
  background-position: center !important;
  background-repeat: no-repeat !important;
  background-color: transparent !important;
  width: 34px !important; 
  height: 34px !important;
  padding: 0 !important; /* 杀掉自带边距防止被挤压 */
  border: none !important;
  opacity: 1 !important;
}

/* ---------------------------------------
   全新的底栏设计：毛玻璃底栏 + 药丸包裹所有按钮
--------------------------------------- */
/* 整个底栏恢复全宽毛玻璃 */
div.chat-detail-screen .input-area-custom { 
  position: relative !important; 
  background: rgba(255, 255, 255, 0.15) !important;
  backdrop-filter: blur(25px) !important;
  -webkit-backdrop-filter: blur(25px) !important;
  border-top: 1px solid rgba(0, 0, 0, 0.05) !important;
  margin: 0 !important; /* 占满底部 */
  padding: 10px 16px !important; /* 左右留白16px */
  z-index: 999 !important; /* 极高层级，防止弹出菜单被系统的隐形遮罩盖住 */
}

/* 强杀输入框本体和原生胶囊的所有背景 */
div.chat-detail-screen .input-action-bar-custom,
div.chat-detail-screen .input-box-custom {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}
/* 去掉自带的 placeholder */
div.chat-detail-screen .input-box-custom::-webkit-input-placeholder { color: transparent !important; text-indent: -9999px !important; }
div.chat-detail-screen .input-box-custom::-moz-placeholder { color: transparent !important; text-indent: -9999px !important; }
div.chat-detail-screen .input-box-custom::placeholder { color: transparent !important; text-indent: -9999px !important; }

/* 取消原有的伪元素毛玻璃 */
div.chat-detail-screen .input-area-custom::before { display: none !important; } 

/* 用 ::after 画一个巨大的粉色药丸背景，从左到右包裹所有按钮！ */
div.chat-detail-screen .input-area-custom::after {
  content: "" !important;
  position: absolute !important;
  left: 16px !important; 
  right: 16px !important; 
  top: 50% !important;
  transform: translateY(-50%) !important;
  height: 44px !important;
  background: #E5F9FF !important; /* 同款浅蓝色 */
  border-radius: 22px !important;
  z-index: -1 !important;
}

/* 把你的专属文字写在输入框内部的伪元素里 */
div.chat-detail-screen .input-area-custom::before {
  content: "布朗尼 泡芙 千层 ⦁֊⦁ಣ" !important;
  position: absolute !important;
  left: 60px !important; /* 恢复原本位置 */
  top: 50% !important;
  transform: translateY(-50%) !important;
  color: #a3a3a3 !important;
  font-size: 13px !important;
  pointer-events: none !important;
  z-index: 2 !important;
  display: block !important;
}
div.chat-detail-screen .input-area-custom:focus-within::before { display: none !important; }

/* 微调加号按钮位置（整体上移2px） */
div.chat-detail-screen .input-btn-plus {
  transform: translateY(-5px) !important;
}

/* =======================================
   3. 默认横排 + 方圆头像
======================================= */
:root {
  --avatar-radius: 9px;
  --plain-avatar-radius: 9px;
}

/* 双方头像回到气泡两侧，每条消息保留相同的头像栏宽度。 */
div.chat-detail-screen .msg-bubble-wrapper.msg-them {
  flex-direction: row !important;
  align-items: flex-start !important;
  gap: 10px !important;
}
div.chat-detail-screen .msg-bubble-wrapper.msg-me {
  flex-direction: row !important;
  align-items: flex-start !important;
  gap: 10px !important;
}
div.chat-detail-screen .msg-avatar-them-container,
div.chat-detail-screen .msg-avatar-me-container {
  display: flex !important;
  flex: 0 0 34px !important;
  width: 34px !important;
  height: 34px !important;
  margin: 0 !important;
  align-self: flex-start !important;
  visibility: visible !important;
  opacity: 1 !important;
}
div.chat-detail-screen .msg-avatar-them-container,
div.chat-detail-screen .msg-avatar-me-container,
div.chat-detail-screen .msg-avatar-them-inner,
div.chat-detail-screen .msg-avatar-me-inner,
div.chat-detail-screen .msg-avatar-them-container img,
div.chat-detail-screen .msg-avatar-me-container img,
div.chat-detail-screen .msg-avatar-custom {
  border-radius: 9px !important;
  overflow: hidden !important;
}

/* =======================================
   4. 文字气泡：柔和胶囊形
======================================= */
/* 特殊卡片保留各自底色；这里收紧普通文字气泡的高度。 */
div.chat-detail-screen .bubble-them-custom:not(:has([class*="card"], .msg-image-wrapper, .voice-msg)),
div.chat-detail-screen .msg-plain-them:not(:has([class*="card"], .msg-image-wrapper, .voice-msg)) {
  background: #f1f2f3 !important;
  color: #000000 !important;
