.msg-translation-detached-them {
  align-self: flex-start !important;
  margin-left: 12px !important;
  margin-right: auto !important;
}

.msg-translation-detached-me {
  align-self: flex-end !important;
  margin-right: 12px !important;
  margin-left: auto !important;
}

/* ============================================================
   9. 转账卡片（2:1 比例 + 垂直居中）
   ============================================================ */

.msg-transfer-card {
  width: 220px !important;
  height: 110px !important;
  aspect-ratio: 2 / 1 !important;
  background: var(--transfer-card-bg) !important;
  border-radius: 10px !important;
  border: 1px solid var(--chat-header-border) !important;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15) !important;
  padding: 0 16px !important;
  box-sizing: border-box !important;
  display: flex !important;
  flex-direction: column !important;
  justify-content: center !important;
  overflow: hidden !important;
}

.msg-transfer-card [class*="transfer-icon"],
.msg-transfer-card [class*="icon-wrap"],
.msg-transfer-card [class*="icon-bg"],
.msg-transfer-card [class*="dot"],
.msg-transfer-card [class*="badge"],
.msg-transfer-card .msg-transfer-label,
.msg-transfer-card [class*="header"],
.msg-transfer-card .msg-transfer-check,
.msg-transfer-card [class*="transfer-check"],
.msg-transfer-card [class*="check"],
.msg-transfer-card.msg-transfer-success svg,
.msg-transfer-card [class*="success"] svg,
.msg-transfer-card svg.success {
  display: none !important;
}

.msg-transfer-card [class*="subtitle"],
.msg-transfer-card [class*="title"],
.msg-transfer-card .msg-transfer-subtitle {
  color: var(--theme-text-sub) !important;
  font-size: 13px !important;
  font-weight: 500 !important;
  line-height: 1.2 !important;
  margin: 0 0 2px 0 !important;
}

.msg-transfer-card [class*="amount"],
.msg-transfer-card .msg-transfer-amount {
  color: var(--transfer-amount-color) !important;
  -webkit-text-fill-color: var(--transfer-amount-color) !important;
  font-size: 22px !important;
  font-weight: 700 !important;
  line-height: 1.1 !important;
  margin: 0 0 5px 0 !important;
}

.msg-transfer-card [class*="divider"],
.msg-transfer-card hr {
  height: 1px !important;
  background-color: var(--chat-header-border) !important;
  border: none !important;
  margin: 0 0 6px 0 !important;
  padding: 0 !important;
  width: 100% !important;
}

.msg-transfer-card [class*="status"],
.msg-transfer-card .msg-transfer-status-text {
  color: var(--theme-text-sub) !important;
  font-size: 11px !important;
  line-height: 1.2 !important;
  margin: 0 !important;
  display: block !important;
}

/* ============================================================
   10. 时间戳与分割线（防撞缓冲区）
   ============================================================ */

.timestamp-custom,
.date-divider-custom {
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;
  margin-top: 20px !important;                  /* 核心：上方留足 20px 防撞 */
  margin-bottom: -10px !important;              /* 紧凑贴合下方 */
  padding: 4px 0 !important;
  position: relative !important;
  z-index: 5 !important;
  color: var(--theme-text-sub) !important;
}

.timestamp-custom::before {
  content: "以下就是最新消息" !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 85% !important;
  max-width: 280px !important;
  color: var(--theme-text-sub) !important;
  font-size: 11px !important;
  font-weight: 400 !important;
  line-height: 1 !important;
  margin-bottom: 8px !important;
  text-align: center !important;
  pointer-events: none !important;
  background-image: 
    linear-gradient(to right, transparent, var(--theme-divider-line)),
    linear-gradient(to right, var(--theme-divider-line), transparent) !important;
  background-position: left center, right center !important;
  background-size: calc(50% - 65px) 1px, calc(50% - 65px) 1px !important;
  background-repeat: no-repeat !important;
}

/* 换人间距 */
.msg-bubble-wrapper.is-last,
.msg-bubble-wrapper.is-single,
.msg-them.is-last,
.msg-them.is-single,
.msg-me.is-last,
.msg-me.is-single {
  margin-bottom: -6px !important;
}

/* ============================================================
   11. 拍一拍
   ============================================================ */

@keyframes nuo-bubble-live-left {
  0% {
    opacity: 0;
    transform: translate(-50%, 0) scale(0.2) rotate(0deg);
  }
  15% {
    opacity: 1;
    transform: translate(calc(-50% - 12px), -18px) scale(1.3) rotate(-14deg);
  }
  40% {
    opacity: 0.9;
    transform: translate(calc(-50% + 10px), -44px) scale(1.1) rotate(12deg);
  }
  70% {
    opacity: 0.7;
    transform: translate(calc(-50% - 18px), -72px) scale(0.9) rotate(-18deg);
  }
  100% {
    opacity: 0;
    transform: translate(calc(-50% + 4px), -102px) scale(0.3) rotate(20deg);
  }
}

@keyframes nuo-bubble-live-right {
  0% {
    opacity: 0;
    transform: translate(-50%, 0) scale(0.2) rotate(0deg);
  }
  15% {
    opacity: 1;
    transform: translate(calc(-50% + 14px), -16px) scale(1.2) rotate(15deg);
  }
  45% {
    opacity: 0.9;
    transform: translate(calc(-50% - 14px), -46px) scale(1.0) rotate(-12deg);
  }
  75% {
    opacity: 0.65;
    transform: translate(calc(-50% + 20px), -78px) scale(0.8) rotate(22deg);
  }
  100% {
    opacity: 0;
    transform: translate(calc(-50% - 8px), -108px) scale(0.3) rotate(-14deg);
  }
}

[class*="pat-bounce"],
[class*="pat-avatar"],
.msg-avatar-them-container:active,
.msg-avatar-me-container:active {
  position: relative !important;
  overflow: visible !important;
}

[class*="pat-bounce"]::before,
[class*="pat-avatar"]::before,
.msg-avatar-them-container:active::before {
  content: "🤍" !important;
  position: absolute !important;
  left: 30% !important;
  top: -12px !important;
  font-size: 16px !important;
  filter: drop-shadow(0 0 6px rgba(255, 255, 255, 0.9)) !important;
  pointer-events: none !important;
  z-index: 60 !important;
  animation: nuo-bubble-live-left 1.4s cubic-bezier(0.25, 1, 0.5, 1) forwards !important;
}

[class*="pat-bounce"]::after,
[class*="pat-avatar"]::after,
.msg-avatar-them-container:active::after {
  content: "♡" !important;
  position: absolute !important;
  left: 70% !important;
  top: -12px !important;
  font-size: 18px !important;
  font-weight: bold !important;
  color: #ffffff !important;
  filter: drop-shadow(0 0 6px rgba(255, 255, 255, 0.9)) !important;
  pointer-events: none !important;
  z-index: 60 !important;
  animation: nuo-bubble-live-right 1.4s cubic-bezier(0.25, 1, 0.5, 1) forwards !important;
}

.nuo-pat-msg {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  margin: 8px auto !important;
  padding: 4px 14px !important;
